import { Agent, Event, Tool } from '@agent-factory/sdk';

/**
 * topicTagAgent
 * Subscribes ARTICLE_SUBMITTED. Loads taxonomy skill, classifies article, and extracts entities.
 */
export default class TopicTagAgent extends Agent {
  async onArticleSubmitted(event: Event) {
    const { title, content } = event.payload;

    // 1. List and Load Skill
    const skills = await this.tools.skills.list_skills({ query: 'topic-taxonomy' });
    let taxonomySkill = null;
    if (skills && skills.length > 0) {
      taxonomySkill = await this.tools.skills.load_skill({ name: 'topic-taxonomy' });
    }

    // 2. Process Content (Simulated logic based on system prompt)
    // In real runtime, the LLM uses the system_prompt and loaded skill to generate this.
    const result = await this.ask({
      prompt: `Please classify this article and extract entities based on the following taxonomy: ${JSON.stringify(taxonomySkill)}`,
      input: { title, content }
    });

    // 3. Emit Tagged Event
    await this.emit('ARTICLE_TAGGED', {
      title,
      content,
      tags: result.tags || ['General'],
      entities: result.entities || []
    });
  }
}

import { Agent, Event } from '@agent-factory/sdk';

/**
 * claimExtractAgent
 * Subscribes ARTICLE_TAGGED. Loads claim-extraction skill and identifies factual claims.
 */
export default class ClaimExtractAgent extends Agent {
  async onArticleTagged(event: Event) {
    const { title, content, tags, entities } = event.payload;

    // 1. Load Extraction Skill
    const skills = await this.tools.skills.list_skills({ query: 'claim-extraction' });
    let extractionSkill = null;
    if (skills && skills.length > 0) {
      extractionSkill = await this.tools.skills.load_skill({ name: 'claim-extraction' });
    }

    // 2. Extract Claims
    const result = await this.ask({
      prompt: `Extract factual claims and verification queries based on: ${JSON.stringify(extractionSkill)}`,
      input: { title, content, tags }
    });

    // 3. Emit Claims Extracted Event
    await this.emit('CLAIMS_EXTRACTED', {
      claims: result.claims || [],
      context: { title, content, tags, entities }
    });
  }
}

import { Agent, Event } from '@agent-factory/sdk';

/**
 * briefAgent
 * Subscribes CLAIMS_EXTRACTED. Assembles HTML brief and persists it.
 */
export default class BriefAgent extends Agent {
  async onClaimsExtracted(event: Event) {
    const { claims, context } = event.payload;

    // 1. Load Brief Template Skill
    const skills = await this.tools.skills.list_skills({ query: 'brief-template' });
    let templateSkill = null;
    if (skills && skills.length > 0) {
      templateSkill = await this.tools.skills.load_skill({ name: 'brief-template' });
    }

    // 2. Generate HTML Brief
    const briefResult = await this.ask({
      prompt: `Assemble an HTML brief using the template: ${JSON.stringify(templateSkill)}`,
      input: { claims, context }
    });

    const fileName = `brief_${Date.now()}.html`;

    // 3. Persist to Disk
    await this.tools.writeBriefToDisk({
      path: fileName,
      content: briefResult.htmlContent
    });

    // 4. Emit Terminal Event
    await this.emit('BRIEF_GENERATED', {
      file_path: fileName,
      brief_title: context.title
    });
  }
}
